import{_ as r,o as t,c as a,a2 as n}from"./chunks/framework.CvydjLy7.js";const u=JSON.parse('{"title":"生产就绪：Actuator 与可观测性","description":"","frontmatter":{"title":"生产就绪：Actuator 与可观测性"},"headers":[{"level":2,"title":"本篇小节","slug":"本篇小节","link":"#本篇小节","children":[]}],"relativePath":"ch10/index.md","filePath":"ch10/index.md","lastUpdated":1789497795000}'),i={name:"ch10/index.md"};function o(c,e,l,s,h,g){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="生产就绪-actuator-与可观测性" tabindex="-1">生产就绪：Actuator 与可观测性 <a class="header-anchor" href="#生产就绪-actuator-与可观测性" aria-label="Permalink to &quot;生产就绪：Actuator 与可观测性&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本篇对应官方章节</p><p><a href="https://docs.spring.io/spring-boot/reference/actuator/index.html" target="_blank" rel="noreferrer">Actuator 总览</a> · <a href="https://docs.spring.io/spring-boot/reference/actuator/enabling.html" target="_blank" rel="noreferrer">启用端点</a> · <a href="https://docs.spring.io/spring-boot/reference/actuator/endpoints.html" target="_blank" rel="noreferrer">端点清单</a> · <a href="https://docs.spring.io/spring-boot/reference/actuator/metrics.html" target="_blank" rel="noreferrer">指标</a> · <a href="https://docs.spring.io/spring-boot/reference/actuator/loggers.html" target="_blank" rel="noreferrer">日志运行时调整</a> · <a href="https://docs.spring.io/spring-boot/reference/actuator/observability.html" target="_blank" rel="noreferrer">可观测性</a> · <a href="https://docs.spring.io/spring-boot/reference/actuator/tracing.html" target="_blank" rel="noreferrer">追踪</a></p></div><p>代码写完、测试跑绿，接下来要面对的是另一个问题：<strong>它上线以后，你怎么知道它好不好？</strong></p><p>日志只能事后翻，报错要等用户来投诉。真正能提前发现问题的，是三类东西：进程还能不能接流量（健康检查）、活动用得怎么样（指标）、出问题时能不能不改配置地拿到更多线索（运行时调日志级别）。Actuator 把这三件事做成了现成的端点。</p><p>这一篇回答四个问题：</p><ul><li><strong>暴露哪些、藏起哪些</strong>：默认值是什么，为什么不该写通配符，以及为什么“没暴露的端点”返回 404 而不是 403</li><li><strong>健康检查怎么写</strong>：内置了哪些组件、存活探针与就绪探针为什么必须分开、自定义检查怎么把细节带出来</li><li><strong>指标怎么读怎么写</strong>：<code>MeterRegistry</code> 的正确用法、指标名到 Prometheus 文本的转换规则，以及测试环境里指标被换掉这件事</li><li><strong>端点本身怎么防护</strong>：<code>EndpointRequest</code> 在 4.x 换了模块和包名，以及端点安全该怎么配</li></ul><p>配套工程是 <code>activity-server-observability</code>，它复用前面几篇的分层代码，把篇幅留给可观测性本身。全篇 22 个用例，<strong>6.9 秒全绿</strong>，不需要任何外部中间件。</p><hr><h2 id="本篇小节" tabindex="-1">本篇小节 <a class="header-anchor" href="#本篇小节" aria-label="Permalink to &quot;本篇小节&quot;">​</a></h2><ul><li><a href="/backend-engineering-course/ch10/01.html">10.1 依赖与暴露面：先把该藏的藏起来</a></li><li><a href="/backend-engineering-course/ch10/02.html">10.2 4.x 把 Actuator 拆成了什么样</a></li><li><a href="/backend-engineering-course/ch10/03.html">10.3 健康检查：内置组件与自定义实现</a></li><li><a href="/backend-engineering-course/ch10/04.html">10.4 存活与就绪：接 K8s 探针</a></li><li><a href="/backend-engineering-course/ch10/05.html">10.5 info 端点：为什么配了 <code>info.*</code> 却看不到</a></li><li><a href="/backend-engineering-course/ch10/06.html">10.6 指标：Micrometer 与自定义 Meter</a></li><li><a href="/backend-engineering-course/ch10/07.html">10.7 Prometheus 端点：实测输出与命名转换</a></li><li><a href="/backend-engineering-course/ch10/08.html">10.8 测试环境里指标导出被换掉了</a></li><li><a href="/backend-engineering-course/ch10/09.html">10.9 运行时改日志级别</a></li><li><a href="/backend-engineering-course/ch10/10.html">10.10 自定义端点：<code>@Endpoint</code></a></li><li><a href="/backend-engineering-course/ch10/11.html">10.11 可观测性与追踪</a></li><li><a href="/backend-engineering-course/ch10/12.html">10.12 端点安全：把暴露面收回来</a></li><li><a href="/backend-engineering-course/ch10/13.html">10.13 问题速查</a></li><li><a href="/backend-engineering-course/ch10/14.html">10.14 小结与下一步</a></li></ul>',10)])])}const f=r(i,[["render",o]]);export{u as __pageData,f as default};
